        </Box>
        {/* 남는 높이를 띄워 알과 박스를 패널 바닥에 붙인다. 내용이 길면 내용 바로 아래에 온다 */}
        {nestScene && Raster && (
          <Box marginTop={1} flexDirection="column">
            {/* 부화한 포켓몬은 세션을 닫지 않아도 박스로 보낼 수 있다 */}
            {eggsOnScreen(nestScene.input, nestScene.columns)
              .filter(egg => egg.stage === 'hatched')
              .map(egg => (
                <Button key={`send-${egg.key}`} label={`Send to PC BOX · ${egg.label}`} onPress={() => sendToBox($, egg.key)} />
              ))}
            {(arrivalMounted = arrivalStep(now) !== null) && (
              // 막 온 전설의 등장 장면을 알과 DAY CARE 위에 겹쳐 띄운다. 다른 줄을 밀어내지 않는다
              <Box position="absolute" top={0} width={nestScene.columns} justifyContent="center">
                <Raster
                  key="arrival"
                  columns={Math.min(nestScene.columns, ARRIVAL_COLUMNS)}
                  rows={ARRIVAL_ROWS}
                  cells={arrivalCells(nestScene.columns, now)}
                />
              </Box>
            )}
            {nestScene.rows > 0 && (
              <Raster key="nest" columns={nestScene.columns} rows={nestScene.rows} cells={nestCells(nestScene, now)} />
            )}
            {wild && (
              // 야생 전설은 몬스터볼을 던지거나 Run 할 때까지(최대 한 시간) 남는다
              <Box flexDirection="column" alignItems="center" width={nestScene.columns}>
                {(() => {
                  const image = drawPortrait(wild.species, lookupSprite)
                  return image && <Raster key="wild" columns={image.columns} rows={image.rows} cells={base64Of(image.cells)} />
                })()}
                <Text bold color="#ffe080">
                  A wild {wild.name.toUpperCase()} appeared!
                </Text>
                <Box>
                  <Button key="encounter-throw" label="Throw POKé BALL" onPress={() => answerEncounter($, 'throw')} />
                  <Button key="encounter-run" label="Run" onPress={() => answerEncounter($, 'run')} />
                </Box>
              </Box>
            )}
            {gone && (
              // 놓친 전설은 사용자가 닫을 때까지 안내가 남는다
              <Box justifyContent="center" width={nestScene.columns}>
                <Text dimColor>Oh no! {gone.toUpperCase()} fled... </Text>
                <Button key="fled-close" label="Close" onPress={() => answerEncounter($, 'dismiss')} />
              </Box>
            )}
            <Box backgroundColor="#c8782a" width={nestScene.columns} paddingX={1}>
              {/* 머리줄을 누르면 키우미집 풀밭을 접거나 편다 */}
              <Button
                plain
                key="daycare-toggle"
                onPress={() => {
                  daycareCollapsed = !daycareCollapsed
                  $.ui.invalidate('ui.render')
                }}
              >
                <Text bold color="#ffffff">
                  {daycareCollapsed ? '▸' : '▾'} DAY CARE
                </Text>
                {/* 키우미집에 맡긴 포켓몬은 일한 만큼 경험치를 얻는다. 원작의 키우미집처럼 */}
                {boxHeader.lead && <Text color="#ffe080">{`  ${boxHeader.lead}`}</Text>}
              </Button>
              <Box flexGrow={1} />
              <Text bold color="#ffe080">
                {nestScene.input.daycare.length}
              </Text>
            </Box>
            {!daycareCollapsed && (
              <Raster
                key="daycare"
                columns={nestScene.columns}
                rows={(daycareRowsDrawn = daycareGroundRows(walkerOf(nestScene, now) !== undefined))}
                cells={daycareCells(nestScene, now)}
              />
            )}
            {(evolveCaptionDrawn = evolveCaption(nestScene, now)) && (
              <Box paddingX={1}>
                <Text bold wrap="truncate-end">
                  {evolveCaptionDrawn}
                </Text>
              </Box>
            )}
            <Box backgroundColor="#3a6ea5" width={nestScene.columns} paddingX={1} marginTop={1}>
              {/* 머리줄을 누르면 박스를 접거나 편다 */}
              <Button
                plain
                key="box-toggle"
                onPress={() => {
                  boxCollapsed = !boxCollapsed
                  $.ui.invalidate('ui.render')
                }}
              >
                <Text bold color="#ffffff">
                  {boxCollapsed ? '▸' : '▾'} PC BOX
                  {!boxCollapsed &&
                    boxPages(nestScene.input) > 1 &&
                    `  ${boxPageOf(nestScene.input) + 1}/${boxPages(nestScene.input)}`}
                </Text>
              </Button>
              <Box flexGrow={1} />
              <Text bold color="#ffe080">
                {boxHeader.count}
              </Text>
            </Box>
            {!boxCollapsed && (
              // 원작 골드 버전의 PC BOX 처럼 한 줄에 한 마리씩 이름과 속성을 글자로 보인다. 줄을 누르면 펼친다
              <Box flexDirection="column" width={nestScene.columns}>
                {boxOnPage(nestScene.input).map(entry => {
                  const row = boxRows.get(entry.key)
                  if (!row) {
                    return null
                  }
                  const isLead = entry.key === nestScene!.input.lead
                  return (
                    <Box key={`box-${entry.key}`} flexDirection="column">
                      <Box paddingX={1}>
                        <Box flexShrink={1}>
                          <Button
                            plain
                            key={`box-row-${entry.key}`}
                            onPress={() => {
                              boxOpen = boxOpen === entry.key ? null : entry.key
                              if (row.isNew) {
                                void markSeen($, entry.key, nestScene!.input.box)
                              }
                              $.ui.invalidate('ui.render')
                            }}
                          >
                            <Text wrap="truncate-end" color={isLead ? '#ffe080' : undefined}>
                              {isLead ? '★ ' : '  '}
                              {/* 즐겨찾는 포켓몬은 이름 앞에 분홍 ♥. 아닌 줄은 같은 폭을 비워 이름이 같은 자리에서 시작한다 */}
                              {row.isFavorite ? <Text color="#ff7aa8">♥ </Text> : '  '}
                              {row.name.toUpperCase()}
                              {/* 전설은 금빛 ✦, 귀한 포켓몬은 하늘빛 ✧ */}
                              {row.rarity === 'legend' && <Text color="#ffc840"> ✦</Text>}
                              {row.rarity === 'rare' && <Text color="#80c8ff"> ✧</Text>}
                              {row.isNew && (
                                <Text bold color="#7ee787">
                                  {' '}
                                  NEW
                                </Text>
                              )}
                              {row.types && <Text dimColor>  {row.types}</Text>}
                            </Text>
                          </Button>
                        </Box>
                        <Box flexGrow={1} />
                        <Text dimColor>{row.caught.slice(5)}</Text>
                      </Box>
                      {boxOpen === entry.key && (
                        <Box flexDirection="column" paddingX={4}>
                          {(() => {
                            // 펼친 포켓몬은 원본 크기 도트로 보인다. 받기 전에는 글자만 보인다
                            const image = drawPortrait(entry.species, lookupSprite)
                            return (
                              image && (
                                <Raster key={`box-portrait-${entry.key}`} columns={image.columns} rows={image.rows} cells={base64Of(image.cells)} />
                              )
                            )
                          })()}
                          <Text dimColor wrap="truncate-end">
                            caught {row.caught} · {entry.label}
                            {row.rarity === 'legend' ? ' · LEGENDARY' : row.rarity === 'rare' ? ' · RARE' : ''}
                          </Text>
                          <Box>
                            <Button
                              key={`favorite-${entry.key}`}
                              label={row.isFavorite ? '♡ Unfavorite' : '♥ Favorite'}
                              onPress={() => void toggleFavorite($, entry.key)}
                            />
                          </Box>
                          {row.canLead && (
                            <Box>
                              <Button key={`lead-${entry.key}`} label="Leave at DAY CARE" onPress={() => pickLead($, entry.key)} />
                            </Box>
                          )}
                          {isLead && (
                            <Box>
                              <Button key={`takeback-${entry.key}`} label="Take back" onPress={() => pickLead($, TAKE_BACK)} />
                            </Box>
                          )}
                        </Box>
                      )}
                    </Box>
                  )
                })}
              </Box>
            )}
            {!boxCollapsed && boxPages(nestScene.input) > 1 && (
              <Box justifyContent="center">
                <Button key="box-prev" label="◀ Prev" onPress={() => turnBox($, -1)} />
                <Button key="box-next" label="Next ▶" onPress={() => turnBox($, 1)} />
              </Box>
            )}
          </Box>
        )}
      </Box>
    )
  })
}

